def regex_search(pattern: str, text: str) -> bool:
    def parse_pattern(p: str):
        n = len(p)

        def parse_alternation(i: int):
            alternatives = []
            while True:
                alt, i = parse_concatenation(i)
                alternatives.append(alt)
                if i < n and p[i] == '|':
                    i += 1
                    continue
                break
            return alternatives, i

        def parse_concatenation(i: int):
            nodes = []
            while i < n and p[i] not in '|)':
                if p[i] in '*+?':
                    raise ValueError("quantifier with no preceding element")
                node, i = parse_atom_with_quantifier(i)
                nodes.append(node)
            return nodes, i

        def parse_atom_with_quantifier(i: int):
            if i >= n:
                raise ValueError("unexpected end of pattern")

            if p[i] == '(':
                i += 1
                children, i = parse_alternation(i)
                if i >= n or p[i] != ')':
                    raise ValueError("unbalanced group")
                i += 1
                base = ('alt', children)
            elif p[i] == '^':
                i += 1
                base = ('anchor', 0)
            elif p[i] == '$':
                i += 1
                base = ('anchor', 1)
            elif p[i] == '.':
                i += 1
                base = ('any',)
            elif p[i] == '\\':
                if i + 1 >= n:
                    raise ValueError("trailing backslash")
                base = ('lit', p[i + 1])
                i += 2
            elif p[i] == '[':
                ranges, neg, i = parse_class(i)
                base = ('class', ranges, neg)
            else:
                base = ('lit', p[i])
                i += 1

            quant = None
            if i < n and p[i] in '*+?':
                if base[0] == 'anchor':
                    raise ValueError("cannot quantify ^ or $")
                quant = p[i]
                i += 1
                if i < n and p[i] in '*+?':
                    raise ValueError("stacked quantifier")
                base = ('quant', quant, base)

            return base, i

        def parse_class(i: int):
            i += 1
            neg = False
            if i < n and p[i] == '^':
                neg = True
                i += 1

            if i >= n:
                raise ValueError("unterminated character class")
            if p[i] == ']':
                raise ValueError("empty character class")

            ranges = []

            def read_char(j: int):
                if j >= n:
                    raise ValueError("unexpected end inside character class")
                if p[j] == '\\':
                    if j + 1 >= n:
                        raise ValueError("bad escape in character class")
                    return p[j + 1], j + 2
                return p[j], j + 1

            while True:
                if i >= n:
                    raise ValueError("unterminated character class")
                if p[i] == ']':
                    i += 1
                    break

                x, i = read_char(i)

                if i < n and p[i] == '-':
                    if i + 1 < n and p[i + 1] != ']':
                        i += 1
                        y, i = read_char(i)
                        if ord(x) > ord(y):
                            raise ValueError("bad character range")
                        ranges.append((ord(x), ord(y)))
                        continue
                    ranges.append((ord(x), ord(x)))
                    continue

                ranges.append((ord(x), ord(x)))

            if not ranges:
                raise ValueError("empty character class")

            return tuple(ranges), neg, i

        alternatives, i = parse_alternation(0)
        if i != n:
            raise ValueError("unbalanced parenthesis")
        return alternatives

    def compile_ast(ast):
        states = []

        def new_state():
            states.append([])
            return len(states) - 1

        def compile_alt(alternatives):
            in_state = new_state()
            out_state = new_state()
            if not alternatives:
                states[in_state].append((0, out_state))
                return in_state, out_state

            for alt in alternatives:
                a_in, a_out = compile_seq(alt)
                states[in_state].append((0, a_in))
                states[a_out].append((0, out_state))
            return in_state, out_state

        def compile_seq(nodes):
            if not nodes:
                in_state = new_state()
                out_state = new_state()
                states[in_state].append((0, out_state))
                return in_state, out_state

            in_state = new_state()
            cur = in_state
            for node in nodes:
                n_in, n_out = compile_node(node)
                states[cur].append((0, n_in))
                cur = n_out
            return in_state, cur

        def compile_node(node):
            kind = node[0]

            if kind == 'lit':
                in_state = new_state()
                out_state = new_state()
                states[in_state].append((2, out_state, node[1]))
                return in_state, out_state

            if kind == 'any':
                in_state = new_state()
                out_state = new_state()
                states[in_state].append((3, out_state))
                return in_state, out_state

            if kind == 'class':
                in_state = new_state()
                out_state = new_state()
                states[in_state].append((4, out_state, node[1], node[2]))
                return in_state, out_state

            if kind == 'anchor':
                in_state = new_state()
                out_state = new_state()
                states[in_state].append((1, out_state, node[1]))
                return in_state, out_state

            if kind == 'alt':
                return compile_alt(node[1])

            if kind == 'quant':
                quant = node[1]
                base_in, base_out = compile_node(node[2])
                in_state = new_state()
                out_state = new_state()

                if quant == '*':
                    states[in_state].append((0, out_state))
                    states[in_state].append((0, base_in))
                    states[base_out].append((0, base_in))
                    states[base_out].append((0, out_state))
                elif quant == '+':
                    states[in_state].append((0, base_in))
                    states[base_out].append((0, base_in))
                    states[base_out].append((0, out_state))
                elif quant == '?':
                    states[in_state].append((0, out_state))
                    states[in_state].append((0, base_in))
                    states[base_out].append((0, out_state))

                return in_state, out_state

            raise ValueError("invalid AST node")

        start_state, accept_state = compile_node(('alt', ast))
        return states, start_state, accept_state

    ast = parse_pattern(pattern)
    states, start_state, accept_state = compile_ast(ast)

    def epsilon_closure(seeds, pos, text_len):
        seen = set()
        stack = []

        def push(state):
            if state not in seen:
                seen.add(state)
                stack.append(state)

        for st in seeds:
            push(st)
        push(start_state)

        while stack:
            st = stack.pop()
            for tr in states[st]:
                t = tr[0]
                if t == 0:
                    push(tr[1])
                elif t == 1:
                    assertion_kind = tr[2]
                    if assertion_kind == 0:
                        if pos == 0:
                            push(tr[1])
                    else:
                        if pos == text_len:
                            push(tr[1])

        return seen

    def class_matches(ch, ranges, neg):
        cp = ord(ch)
        inside = False
        for lo, hi in ranges:
            if lo <= cp <= hi:
                inside = True
                break
        return (not inside) if neg else inside

    n = len(text)
    active = set()
    pos = 0

    while pos <= n:
        active = epsilon_closure(active, pos, n)

        if accept_state in active:
            return True

        if pos == n:
            break

        ch = text[pos]
        nxt = set()

        for st in active:
            for tr in states[st]:
                t = tr[0]
                if t == 2:
                    if tr[2] == ch:
                        nxt.add(tr[1])
                elif t == 3:
                    nxt.add(tr[1])
                elif t == 4:
                    if class_matches(ch, tr[2], tr[3]):
                        nxt.add(tr[1])

        active = nxt
        pos += 1

    return False
